"""Calculate calibrated solar energy for the UTC day of 2024-03-15."""

import json
from datetime import datetime, time, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATA = Path("/app/dataset")
DAY_START = datetime(2024, 3, 15, tzinfo=timezone.utc)
DAY_END = datetime(2024, 3, 16, tzinfo=timezone.utc)


def _timestamp(value: str):
    """Accept only the two unambiguous timestamp formats in the exports."""
    value = value.strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(value, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            pass
    return None


def _number(value: str) -> float:
    """Read ordinary and continental European decimal notation."""
    try:
        value = value.strip()
        if "," in value:
            value = value.replace(".", "").replace(",", ".")
        return float(value)
    except (AttributeError, ValueError):
        return float("nan")


def _read_export(farm_id: str) -> pd.DataFrame:
    path = DATA / f"production_{farm_id}.csv"
    encoding = "utf-16" if path.read_bytes().startswith(b"\xff\xfe") else "utf-8"
    header = path.read_text(encoding=encoding).splitlines()[3]
    separator = ";" if ";" in header else ","
    return pd.read_csv(
        path,
        encoding=encoding,
        sep=separator,
        skiprows=3,
        dtype=str,
        keep_default_na=False,
    )


def _completed_maintenance_utc(farm_id: str, farm_timezone: str):
    # Only the completed events in maintenance_notes.txt are exclusion windows.
    completed = {
        "FARM_C": [(2024, 3, 16, 8, 12)],
        "FARM_F": [(2024, 3, 15, 12, 14)],
    }
    zone = ZoneInfo(farm_timezone)
    for year, month, day, start_hour, end_hour in completed.get(farm_id, []):
        local_start = datetime.combine(
            datetime(year, month, day).date(), time(start_hour), tzinfo=zone
        )
        local_end = datetime.combine(
            datetime(year, month, day).date(), time(end_hour), tzinfo=zone
        )
        yield local_start.astimezone(timezone.utc), local_end.astimezone(timezone.utc)


def answer() -> dict[str, int]:
    farms = pd.read_csv(DATA / "farms.csv")
    registry = pd.read_csv(DATA / "farm_registry.csv")
    farms["farm_name"] = farms["farm_name"].str.strip().str.casefold()
    registry["farm_name"] = registry["farm_name"].str.strip().str.casefold()
    farm_info = registry.merge(farms, on="farm_name", validate="one_to_one")

    calibration = json.loads((DATA / "sensors_calibration.json").read_text())
    sensor_info = calibration["enterprise_platform"]["deployment_environments"][
        "system_config"
    ]["farms"]

    result = {}
    for farm in farm_info.itertuples(index=False):
        settings = sensor_info[farm.farm_id]
        value_col = settings["calibration_data"]["value_column_name"]
        offset = settings["calibration_data"]["calibration_offset"]
        reading_type = settings["sensor_info"]["reading_type"].lower()
        unit = settings["sensor_info"]["unit"].lower()

        export = _read_export(farm.farm_id)
        readings = pd.DataFrame(
            {
                "timestamp": export.iloc[:, 0].map(_timestamp),
                "recorded": export[value_col].map(_number),
                "temperature": export["inverter_temperature_C"].map(_number),
            }
        )
        readings = readings.dropna(subset=["timestamp"])
        # Repeated timestamps contain an earlier corrupted record followed by
        # the corrected export. The last record is the valid one.
        readings = readings.drop_duplicates(subset=["timestamp"], keep="last")

        if reading_type == "power" and len(readings) >= 2:
            gaps = readings["timestamp"].sort_values().diff().dropna()
            gaps = gaps[gaps > pd.Timedelta(0)]
            interval_hours = gaps.mode().iloc[0].total_seconds() / 3600
        else:
            interval_hours = 1.0

        # A spike invalidates subsequent readings for 45 minutes. The spike
        # itself remains a reading unless another rule excludes it.
        spikes = readings.loc[readings["temperature"] > 85, "timestamp"]
        for spike in spikes:
            readings = readings.loc[
                ~(
                    (readings["timestamp"] > spike)
                    & (readings["timestamp"] <= spike + pd.Timedelta(minutes=45))
                )
            ]

        readings = readings.loc[
            (readings["timestamp"] >= DAY_START)
            & (readings["timestamp"] < DAY_END)
        ]
        for start, end in _completed_maintenance_utc(farm.farm_id, farm.timezone):
            readings = readings.loc[
                ~((readings["timestamp"] >= start) & (readings["timestamp"] < end))
            ]

        readings = readings.assign(true_value=readings["recorded"] - offset)
        readings = readings.loc[readings["true_value"] >= 0]

        # Calibration is in the original sensor unit; convert only afterward.
        unit_to_kwh = {
            "kwh": 1.0,
            "mwh": 1000.0,
            "wh": 0.001,
            "btu": 0.00029307107,
            "kw": 1.0,
        }
        energy_kwh = readings["true_value"].sum() * unit_to_kwh[unit]
        if reading_type == "power":
            energy_kwh *= interval_hours
        result[farm.farm_id] = round(energy_kwh)
    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w") as output:
        json.dump(answer(), output, default=list)

